const API_BASE = "[http://127.0.0.1:8000/api](http://127.0.0.1:8000/api)";

export const contentFactory = (mode, token) => {
switch (mode) {
// 📰 Звичайна стаття
case "standard":
return async (articleData) => {
const formData = new FormData();
formData.append("title", articleData.title || "");
formData.append(
"slug",
((articleData.title || "untitled").toLowerCase().replace(/[^a-z0-9]+/g, "-") +
"-" +
Date.now())
);
formData.append("content", articleData.content || "");
formData.append("excerpt", articleData.excerpt || "");
formData.append("category", articleData.category || "sport");
formData.append("is_premium", articleData.is_premium ? "true" : "false");
formData.append("type", "standard");
if (articleData.image) formData.append("image", articleData.image);


    const res = await fetch(`${API_BASE}/articles/`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    if (!res.ok) {
      const errText = await res.text();
      console.error("Помилка створення стандартної статті:", errText);
      throw new Error("Не вдалося створити стандартну статтю");
    }
    return await res.json();
  };

// 📡 Стаття для каналу
case "channel":
  return async (articleData) => {
    const formData = new FormData();
    formData.append("title", articleData.title || "");
    formData.append(
      "slug",
      ((articleData.title || "untitled").toLowerCase().replace(/[^a-z0-9]+/g, "-") +
        "-" +
        Date.now())
    );
    formData.append("content", articleData.content || "");
    formData.append("excerpt", articleData.excerpt || "");
    formData.append("type", "channel");
    formData.append("category", "News"); // дефолт для каналу
    formData.append("is_premium", articleData.is_premium ? "true" : "false");
    if (articleData.channel) formData.append("channel", articleData.channel);
    if (articleData.image) formData.append("image", articleData.image);

    const res = await fetch(`${API_BASE}/articles/`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    if (!res.ok) {
      const errText = await res.text();
      console.error("Помилка створення статті в канал:", errText);
      throw new Error("Не вдалося створити статтю для каналу");
    }
    return await res.json();
  };

default:
  throw new Error("Невідомий тип контенту");


}
};
